  (NULL, 'BH', 'BHD', 70, 'DOMESTIC', NULL, 'Benefit', NULL, NULL, NULL, '5542', NULL, NULL, 0.006000, 0.085, 'BENEFIT Petrol 5542 0.60% cap 0.085'),

