-- ############################################################################
-- FILE 14/23: V2026_08_09_01__ref_bin_range.sql
-- ############################################################################
-- ============================================================================
-- V2026_08_09_01: ref_bin_range — scheme BIN/account-range reference data.
--
-- WHY A RANGE TABLE (alongside the 8-digit ref_bin)
-- -------------------------------------------------
-- Scheme BIN files are RANGE-based, not BIN-based. The Visa BIN list carries
-- 9-digit account ranges that split BELOW the 8-digit boundary (verified in
-- AFS's own file: 402627000-402627001 vs 402627002-402627004 carry different
-- products), so collapsing to 8 digits either loses granularity or explodes
-- to ~50M rows. Ranges load here LOSSLESS (593K rows for the current Visa
-- file); ref_bin (8-digit, manually uploaded CSV/XLSX) stays untouched as the
-- AMS product-type mapping per the 2026-08-08 decision.
--
-- Loaded from Super Admin > BIN Management. File type is detected by NAME:
--   VISA*  -> fixed-width Visa BIN list parser (this table, scheme VISA)
--   T067*  -> rejected until the Mastercard SMS layout doc is provided
--   other  -> CSV/XLSX -> ref_bin (8-digit) as before
--
-- CONFIG ONLY: no ingestion or fee logic reads this table yet.
--
-- range_low/range_high are the file's 9-digit account-range bounds stored
-- zero-padded; lookups compare on the PAN's leading 9 digits. bin6 is the
-- licensed BIN column from the file (may differ from the range prefix).
-- funding_source keeps the raw scheme letter (C/D/P/H/R); card_type is the
-- Acquira-normalized bucket.
--
-- Idempotent + splitter-safe.
-- ============================================================================

CREATE TABLE IF NOT EXISTS ref_bin_range (
    id             BIGSERIAL PRIMARY KEY,
    scheme         VARCHAR(20) NOT NULL,       -- VISA / MASTERCARD
    range_low      VARCHAR(9)  NOT NULL,       -- 9-digit, zero-padded
    range_high     VARCHAR(9)  NOT NULL,
    bin6           VARCHAR(8),                 -- licensed BIN column from the file
    region_code    VARCHAR(2),                 -- scheme region (Visa: 1-6)
    issuer_country VARCHAR(2),                 -- ISO alpha-2 from the file
    product_code   VARCHAR(5),                 -- scheme product id (F, N, C, G1, ...)
    funding_source VARCHAR(2),                 -- raw scheme letter (C/D/P/H/R)
    card_type      VARCHAR(20),                -- normalized CREDIT/DEBIT/PREPAID
    source_file    VARCHAR(200),
    loaded_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_ref_bin_range_lookup ON ref_bin_range (scheme, range_low, range_high);
CREATE INDEX IF NOT EXISTS idx_ref_bin_range_country ON ref_bin_range (issuer_country);

INSERT INTO schema_migration_log (filename) VALUES ('V2026_08_09_01__ref_bin_range.sql') ON CONFLICT (filename) DO NOTHING;


-- ############################################################################
-- FILE 15/23: V2026_08_09_02__mpe_staging.sql
-- ############################################################################
-- ============================================================================
-- V2026_08_09_02: Mastercard IPM MPE (T067/T068) staged intake.
--
-- SCOPE (2026-08-09): STAGE + VALIDATE ONLY. The container format, file
-- header ("UPDATE FILE" / "REPLACEMENT FILE"), IP0000T1 directory and the
-- per-table/final trailers are parsed per the Dual Message Clearing System
-- Parameter Table Layouts DITA documentation (verified field-for-field
-- against AFS's live TT067 delivery). The INNER field mapping of the account
-- range table (IP0040T1) in AFS's extract is an OLDER table edition than the
-- June-2026 manual (declared record length 307 vs manual 313; compressed
-- field order differs), so promotion of ranges into ref_bin_range is
-- deliberately DEFERRED until the T068 full-file replacement confirms the
-- positions empirically. Nothing reads these tables yet.
--
-- mpe_file            one row per uploaded delivery (checksum-deduped)
-- mpe_table_directory the file's own IP0000T1 records, decoded (the file
--                     declares its tables, key positions, record lengths,
--                     versions and 3-char sub-ids)
-- mpe_record          every data record, keyed by table sub-id, raw text
--                     preserved verbatim (fixed-width spaces intact)
--
-- Idempotent + splitter-safe.
-- ============================================================================

CREATE TABLE IF NOT EXISTS mpe_file (
    id               BIGSERIAL PRIMARY KEY,
    file_name        VARCHAR(200) NOT NULL,
    file_type        VARCHAR(10)  NOT NULL,     -- T067 (update) / T068 (replacement)
    header_text      VARCHAR(80),
    created_date     VARCHAR(20),               -- from header, as delivered
    created_time     VARCHAR(20),
    sha256           VARCHAR(64) NOT NULL UNIQUE, -- duplicate-delivery guard
    record_count     INT,
    trailer_total    INT,                       -- final TABLEZZZZ trailer count
    status           VARCHAR(20) NOT NULL,      -- STAGED / COUNT_MISMATCH
    loaded_at        TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS mpe_table_directory (
    id               BIGSERIAL PRIMARY KEY,
    file_id          BIGINT NOT NULL REFERENCES mpe_file(id) ON DELETE CASCADE,
    subject_table    VARCHAR(8)  NOT NULL,      -- e.g. IP0040T1
    subject_name     VARCHAR(30),               -- e.g. ACCOUNT RANGE TABLE
    sub_id           VARCHAR(3),                -- 3-char compressed table id
    key_length       INT,
    key_start        INT,
    rec_len_min      INT,
    rec_len_max      INT,
    version          VARCHAR(8),
    declared_count   INT,                       -- from that table's trailer
    staged_count     INT                        -- records actually staged
);
CREATE INDEX IF NOT EXISTS idx_mpe_dir_file ON mpe_table_directory (file_id);

CREATE TABLE IF NOT EXISTS mpe_record (
    id               BIGSERIAL PRIMARY KEY,
    file_id          BIGINT NOT NULL REFERENCES mpe_file(id) ON DELETE CASCADE,
    sub_id           VARCHAR(3) NOT NULL,
    active_flag      CHAR(1),
    effective_raw    VARCHAR(10),               -- as delivered (edition-dependent format)
    record_text      TEXT NOT NULL              -- verbatim, spaces preserved
);
CREATE INDEX IF NOT EXISTS idx_mpe_record_file_sub ON mpe_record (file_id, sub_id);

INSERT INTO schema_migration_log (filename) VALUES ('V2026_08_09_02__mpe_staging.sql') ON CONFLICT (filename) DO NOTHING;


-- ############################################################################
-- FILE 16/23: V2026_08_09_03__ref_bin_range_19_digits.sql
-- ############################################################################
-- ============================================================================
-- V2026_08_09_03: ref_bin_range ranges normalized to 19 digits (MC + Visa).
--
-- Mastercard IP0040T1 account ranges are 19-digit (PAN-length, e.g.
-- 5102999070500000000-…0999999999); Visa BIN-list ranges are 9-digit
-- prefixes. To let ONE containment lookup serve both schemes, all ranges are
-- stored at 19 digits: a 9-digit Visa prefix range low L / high H becomes
-- L + '0000000000' and H + '9999999999'. Lookups pad the PAN prefix with
-- zeros to 19 and compare lexicographically (zero-padded fixed-width strings
-- compare identically to numerics).
--
-- LOAD SEMANTICS (business-confirmed 2026-08-09):
--   VISA* upload -> full refresh: DELETE all VISA rows, reinsert the file.
--   T068 upload  -> full refresh: DELETE all MASTERCARD rows, decode + insert.
--   T067 upload  -> DELTA ONLY: 'A' records upsert by (range_low, GCMS
--                   product), 'I' records remove that key. Never a mass
--                   delete. Test files T167/T168 stage only.
--
-- Idempotent + splitter-safe. The pad UPDATEs key on length(range_low)=9 so
-- re-runs (and reloads of already-padded data) are no-ops.
-- ============================================================================

ALTER TABLE ref_bin_range ALTER COLUMN range_low  TYPE VARCHAR(19);
ALTER TABLE ref_bin_range ALTER COLUMN range_high TYPE VARCHAR(19);

UPDATE ref_bin_range SET range_low  = range_low  || '0000000000' WHERE LENGTH(range_low)  = 9;
UPDATE ref_bin_range SET range_high = range_high || '9999999999' WHERE LENGTH(range_high) = 9;

-- MC upsert key: one row per (scheme, range_low, product). Partial unique
-- index scoped to MASTERCARD so the Visa full-refresh path (which may carry
-- legitimate duplicate lows across products with NULL product rows) is
-- unaffected.
CREATE UNIQUE INDEX IF NOT EXISTS uq_ref_bin_range_mc_key
    ON ref_bin_range (range_low, COALESCE(product_code, ''))
    WHERE scheme = 'MASTERCARD';

INSERT INTO schema_migration_log (filename) VALUES ('V2026_08_09_03__ref_bin_range_19_digits.sql') ON CONFLICT (filename) DO NOTHING;


-- ############################################################################
-- FILE 17/23: V2026_08_09_04__interchange_normalization.sql
-- ############################################################################
-- ============================================================================
-- V2026_08_09_04: Interchange Fee Normalization (Super Admin correction tool).
--
-- Business context: the fee engine's computed interchange at merchant level is
-- known to be off for some months. Finance supplies the CORRECT month total;
-- this feature KEEPS every transaction's existing interchange and adds the
-- extra (target - current total) on top weighted by VOLUME — merchant share of
-- month volume, then transaction share of merchant volume
-- (new = old + volume_share * extra, largest-remainder reconciliation so the
-- values sum EXACTLY to the target). fact_transaction.interchange_fee is then
-- updated and every summary table rebuilt so all screens show normalized values.
--
-- interchange_normalization_run    — one row per run; re-running a month adds a
--                                    new version and marks the prior APPLIED run
--                                    SUPERSEDED (history is never overwritten).
-- interchange_normalization_detail — per-merchant snapshot: the OLD interchange
--                                    (only surviving record of pre-normalization
--                                    values), weight, and the normalized amount.
--
-- Idempotent + splitter-safe.
-- ============================================================================

CREATE TABLE IF NOT EXISTS interchange_normalization_run (
    run_id                     BIGSERIAL PRIMARY KEY,
    tenant_id                  BIGINT       NOT NULL,
    month_key                  INTEGER      NOT NULL,          -- YYYYMM
    version_no                 INTEGER      NOT NULL DEFAULT 1,
    original_interchange_total NUMERIC(18,4),                  -- system value at preview time
    target_normalized_total    NUMERIC(18,4) NOT NULL,         -- finance-supplied truth
    difference                 NUMERIC(18,4),                  -- target - original
    unattributed_original      NUMERIC(18,4) DEFAULT 0,        -- interchange on merchant-less fact rows (scaled like the rest)
    unattributed_normalized    NUMERIC(18,4) DEFAULT 0,        -- their share of the target
    weighting_base             VARCHAR(30)  NOT NULL DEFAULT 'VOLUME_EXTRA',
    residual_method            VARCHAR(30)  NOT NULL DEFAULT 'LARGEST_REMAINDER',
    currency_scale             INTEGER      NOT NULL DEFAULT 2,
    merchant_count             INTEGER,
    status                     VARCHAR(20)  NOT NULL DEFAULT 'PREVIEW',
                               -- PREVIEW / APPLYING / APPLIED / SUPERSEDED / CANCELLED / FAILED
    status_detail              VARCHAR(500),
    created_by                 VARCHAR(100),
    created_at                 TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    applied_by                 VARCHAR(100),
    applied_at                 TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_ic_norm_run_tenant_month
    ON interchange_normalization_run (tenant_id, month_key);
-- Exactly one live (APPLIED) version per tenant+month; DB-level duplicate guard.
CREATE UNIQUE INDEX IF NOT EXISTS uq_ic_norm_run_applied
    ON interchange_normalization_run (tenant_id, month_key) WHERE status = 'APPLIED';
-- Guard for databases where the table pre-dates the column.
ALTER TABLE interchange_normalization_run
    ADD COLUMN IF NOT EXISTS unattributed_normalized NUMERIC(18,4) DEFAULT 0;

CREATE TABLE IF NOT EXISTS interchange_normalization_detail (
    detail_id              BIGSERIAL PRIMARY KEY,
    run_id                 BIGINT NOT NULL
                           REFERENCES interchange_normalization_run (run_id) ON DELETE CASCADE,
    merchant_id            BIGINT NOT NULL,
    merchant_name          VARCHAR(255),
    txn_count              INTEGER,
    txn_volume             NUMERIC(18,4),
    original_interchange   NUMERIC(18,4),   -- pre-normalization value (audit snapshot)
    weight_pct             NUMERIC(14,10),  -- merchant volume / total volume * 100
    normalized_interchange NUMERIC(18,4),   -- rounded + largest-remainder adjusted
    difference             NUMERIC(18,4)    -- normalized - original
);
CREATE INDEX IF NOT EXISTS idx_ic_norm_detail_run
    ON interchange_normalization_detail (run_id);
CREATE INDEX IF NOT EXISTS idx_ic_norm_detail_merchant
    ON interchange_normalization_detail (merchant_id);

-- Menu: Super Admin ONLY — this tool rewrites fact-level fees.
INSERT INTO sys_menu (menu_name, path, icon_key, category, display_order)
VALUES ('Interchange Normalization', '/admin/interchange-normalization', 'Scale', 'ADMINISTRATION', 18)
ON CONFLICT (path) DO NOTHING;

INSERT INTO sys_group_menu (group_id, menu_id)
SELECT g.group_id, m.menu_id
FROM sys_user_group g, sys_menu m
WHERE g.group_name = 'Super Admin'
  AND m.path = '/admin/interchange-normalization'
ON CONFLICT DO NOTHING;

